"""File to house the Application_AUT Base class and its supporting member functions"""

import logging
from remotesystem import RemoteSystem
import squishtest

logger = logging.getLogger()

class StartWinAutError(Exception):
    """
    Thrown when the startwinaut.exe is fails to launch on a given remote system with a squish server running.
    """
    def __init__(self, serverAddress: str, stderr: str) -> None:
        message = f"""Failed to launch the startwinaut application on server: {serverAddress}.
                {stderr}"""
        super().__init__(message)

def _check_for_running_startwinaut(serverAddress:str, serverPort:int) -> bool:
    """Connects to a remote system running a squish server and performs a command to check if the 'startwinaut.exe' is already running

    :param str serverAddress: IP address of target system running a squish server
    :param int serverPort: Network port of running squish server on target system (Default is 4322)
    :return: True or False
    :rtype bool:
    """
    remotesys = RemoteSystem(host=serverAddress, port=serverPort)
    options = {"timeout": 10}

    find_winaut_pid_command = ["cmd", "/c", "tasklist", "/FI", "IMAGENAME eq startwinaut.exe", "/FO", "LIST", "|", "findstr", "PID:"]
    (exitcode, stdout, stderr) = remotesys.execute(find_winaut_pid_command, options=options)

    remotesys.close()
    if exitcode != "0":
        return False
    return True

def _get_running_aut_pid(serverAddress:str, serverPort:int, autHandle: str, retries: int = 1) -> str:
    """Connects to a remote system running a squish server and performs a command to check if the given AUT is already running
    and returns the PID number as a string

    :param str serverAddress: IP address of target system running a squish server
    :param int serverPort: Network port of running squish server on target system (Default is 4322)
    :param int retries: Number of attempts to get the status of a given AUT process running on a remote system
    :return: PID number as a string
    :rtype str:
    """
    for i in range(retries):
        try:
            remotesys = RemoteSystem(host=serverAddress, port=serverPort)
            options = {"timeout": 10}
            find_pid_command = ["cmd", "/c", "tasklist", "/FI", f"IMAGENAME eq {autHandle}.exe", "/FO", "LIST", "|", "findstr", "PID:"]
            (exitcode, stdout, stderr) = remotesys.execute(find_pid_command, options=options)

            if exitcode != "0":
                raise ValueError(f"Was unable to find a running application with handle: {autHandle}")
            return stdout.split()[1]
        except Exception as e:
            logger.info(f"Squish's RemoteSystem()'s returned an error: {e} . Retrying...")

def _launch_startwinaut(serverAddress:str, serverPort:int, attachPort: str, autPID: str) -> None:
    """Connects to a remote system running a squish server and performs a command to check if the given AUT is already running
    and returns the PID number as a string

    :param str serverAddress: IP address of target system running a squish server
    :param int serverPort: Network port of running squish server on target system (Default is 4322)
    :param str attachPort: Network port for the attach squish server extension
    :param str autPID: PID number of the AUT to be attached to
    """
    remotesys = RemoteSystem(host=serverAddress, port=serverPort)
    options = {"timeout": 10}
    cmd = ["cmd", "/c", "start", "/min", "startwinaut", f"--port={attachPort}", f"--pid={autPID}"]
    (exitcode, stdout, stderr) = remotesys.execute(cmd, options=options)

    if exitcode != "0":
        raise StartWinAutError(serverAddress, stderr)

def _cleanup_startwinaut(serverAddress: str, serverPort: int) -> bool:
    """Closes/ kills any existing startwinaut.exe, hookwinaut.exe, _startwinaut.exe and _hookwinaut.exe
    processes running on the target system.

    :param str serverAddress: IP address of target system running a squish server
    :param int serverPort: Network port of running squish server on target system (Default is 4322)
    :return: True or False
    :rtype bool:
    """
    kill_process_failed = False
    for process in ["startwinaut.exe", "hookwinaut.exe", "_startwinaut.exe", "_hookwinaut.exe"]:
        try:
            remoteOS = RemoteSystem(host=serverAddress, port=serverPort)
            (exit_code, stdout, stderr) = remoteOS.execute(['taskkill', '/F', '/FI', 'IMAGENAME eq {}'.format(process)])

            if exit_code != "0":
                logger.error(f"taskkill command for process: {process} did not run successfully. Exit code: {exit_code}")
                kill_process_failed = True
            else:
                logger.info(f"Process {process} successfully closed.")
        except Exception as e:
            logger.exception(f"_cleanup_startwinaut(): Failed to kill startwinaut process: {e}")
            kill_process_failed = True
    if kill_process_failed:
        return False
    return True

class Application_AUT():
    """Base class for the generation of base values for AUT class objects.

    :param serverAddress: Host IP Address of the system you wish to target with a squish server running
    :type serverAddress: str
    :param serverPort: Network Port number the running squish server. Default value is 4322
    :type serverPort: int, optional
    """
    def __init__(self, serverAddress: str, serverPort: int = 4322) -> None:
        self._squishserver_address: str = serverAddress
        self._squishserver_port: int = serverPort
        self._aut_name: str = ""
        self.app_handle = None
        self.attach_port: str = ""
        self.arguments: str = ""

    @property
    def get_squishserver_address(self):
        return self._squishserver_address

    @property
    def get_squishserver_port(self):
        return self._squishserver_port

    def set_app_context_to_this_aut(self):
        """Sets the Squish test context to the application associated with the instantiated class.
        """
        squishtest.setApplicationContext(self.app_handle) #type: ignore

    def start_aut(self, autTimeout: int = 60) -> None:
        """Launches the AUT with class settings
        :param int autTimeout: Timeout in seconds to wait for the AUT to start. Default is 60 secs (1 minute)
        """
        try:
            if hasattr(squishtest, 'testSettings') and hasattr(squishtest.testSettings, 'setWrappersForApplication'):
                squishtest.testSettings.setWrappersForApplication(self._aut_name, ['Windows']) #type: ignore
        except Exception:
            # testSettings not available in this environment; continue without setting wrappers
            pass
        self.app_handle = squishtest.startApplication('"%s" "%s"' % (self._aut_name, self.arguments), self._squishserver_address, self._squishserver_port, autTimeout) #type: ignore
        return self.app_handle

    def attach_to_aut(self, kill_existing_process: bool=False, launch_new_startwinaut: bool=False, get_running_aut_pid_retries: int=1):
        """Attaches to the AUT with class settings

        :param bool kill_existing_process: Set to True to close all existing startwinaut and hookwinaut processes at the start
        :param bool launch_new_startwinaut: Set to True to start a new startwinaut process and to leave existing startwinaut processes running.
                                            Enable this arg if existing startwinaut processes are used by other AUTs.
        :param int get_running_aut_pid_retries: Number of attempts to get the status of a given AUT process running on a remote system
        """
        # Kills all existing startwinaut and hookwinaut processes
        if kill_existing_process and _check_for_running_startwinaut(self._squishserver_address, self._squishserver_port):
            _cleanup_startwinaut(self._squishserver_address, self._squishserver_port)

        # Launch startwinaut process if not already running or if the kill_existing_process or launch_new_startwinaut args are True
        if not _check_for_running_startwinaut(self._squishserver_address, self._squishserver_port) or launch_new_startwinaut:
            running_aut_pid = _get_running_aut_pid(self._squishserver_address, self._squishserver_port, self._aut_name, get_running_aut_pid_retries)
            _launch_startwinaut(
                self._squishserver_address,
                self._squishserver_port,
                self.attach_port,
                running_aut_pid
                )
        self.app_handle = squishtest.attachToApplication(self._aut_name, self._squishserver_address, self._squishserver_port, 300) #type: ignore
        return self.app_handle